import { OrderSource } from '../../types/kds';

interface Props {
    source: OrderSource;
}

const sourceColors: Record<OrderSource, string> = {
    POS: 'bg-blue-600',
    CALL_CENTER: 'bg-purple-600',
    ONLINE: 'bg-green-600',
    UBER_DIRECT: 'bg-black',
    KIOSK: 'bg-orange-600',
    API: 'bg-gray-600',
};

export function SourceBadge({ source }: Props) {
    return (
        <span
            className={`px-3 py-1 text-xs font-bold text-white rounded ${sourceColors[source]}`}
        >
            {source.replace('_', ' ')}
        </span>
    );
}
