'use client';

import { KDSHeader } from '@/modules/kds/components/KDSHeader';
import { OrderTicket } from '@/modules/kds/components/ticket/OrderTicket';
import { useKDSOrders } from '@/modules/kds/hooks/useKDSOrders';

export default function KDSMasterPage() {
    const { orders } = useKDSOrders();

    return (
        <>
            <KDSHeader />

            <main className="kds-main">
                {orders.length === 0 ? (
                    <div className="kds-empty-state kds-animate-in">
                        <div className="kds-empty-text">
                            Waiting for orders...
                        </div>
                    </div>
                ) : (
                    <div className="kds-ticket-grid kds-animate-in">
                        {orders.map((order) => (
                            <OrderTicket key={order.id} order={order} />
                        ))}
                    </div>
                )}
            </main>
        </>
    );
}
