import { create } from 'zustand';
import { KDSOrder } from '../types/kds';

interface KDSState {
    orders: Record<string, KDSOrder>;

    addOrUpdateOrder: (order: KDSOrder) => void;
    removeOrder: (orderId: string) => void;
    updateOrderStage: (orderId: string, stage: string) => void;
    markDelayed: (orderId: string, reason?: string) => void;
}

export const useKDSStore = create<KDSState>((set) => ({
    orders: {},

    addOrUpdateOrder: (order) =>
        set((state) => ({
            orders: {
                ...state.orders,
                [order.id]: order, // idempotent replacement
            },
        })),

    removeOrder: (orderId) =>
        set((state) => {
            const newOrders = { ...state.orders };
            delete newOrders[orderId];
            return { orders: newOrders };
        }),

    updateOrderStage: (orderId, stage) =>
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        stage,
                        stageStartedAt: new Date().toISOString(),
                    },
                },
            };
        }),

    markDelayed: (orderId, reason) =>
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        isDelayed: true,
                        delayReason: reason,
                    },
                },
            };
        }),
}));
