'use client';

import { useState, useEffect } from 'react';
import { Volume2, VolumeX, Filter } from 'lucide-react';
import { useTenantStore } from '@/app/providers/TenantStoreProvider';

export const KDSHeader: React.FC = () => {
    const { store } = useTenantStore();
    const [currentTime, setCurrentTime] = useState<Date>(new Date());
    const [isSoundEnabled, setIsSoundEnabled] = useState(true);

    useEffect(() => {
        const timer = setInterval(() => {
            setCurrentTime(new Date());
        }, 1000);

        return () => clearInterval(timer);
    }, []);

    const formatTime = (date: Date) => {
        return date.toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
        });
    };

    return (
        <header className="kds-header">
            <div className="kds-header-left">
                <div className="kds-store-name">
                    {store?.name || 'KITCHEN DISPLAY'}
                </div>
            </div>

            <div className="kds-header-center">
                <div className="kds-clock">
                    {formatTime(currentTime)}
                </div>
            </div>

            <div className="kds-header-right">
                <button
                    className="kds-header-btn"
                    onClick={() => setIsSoundEnabled(!isSoundEnabled)}
                    title={isSoundEnabled ? 'Mute' : 'Unmute'}
                >
                    {isSoundEnabled ? <Volume2 size={28} /> : <VolumeX size={28} />}
                </button>

                <button className="kds-header-btn">
                    <Filter size={28} />
                    <span>FILTERS</span>
                </button>
            </div>
        </header>
    );
};
